 "desc": "รายงานข่าวพลังงานประจำวัน: บสย. ออกโครงการ Solar Plus ค้ำสินเชื่อ 1,000 ล้านบาท หนุนผู้รับเหมาโซลาร์ · กระทรวงพลังงานยืนยันยังไม่ยกเลิกแก๊สโซฮอล์ เน้นจูงใจใช้ E20 · แคลิฟอร์เนียเปิดโครงการโซลาร์ + แบตเตอรี่ Lockhart รวม 538.7 MW (ตัวเลขทุกตัวอ้างอิงแหล่งข่าวในคลิปและแคปชั่น)",
