   "title": "บสย. ออกโครงการ Solar Plus ค้ำสินเชื่อ 1,000 ล้านบาท หนุนผู้รับเหมาโซลาร์",
   "video": "v/n1.mp4",
   "poster": "p/n1.jpg",
   "file": "TNS-News_691114_1_บสยSolarPlusค้ำ1000ล้าน_9x16_v1.mp4",
   "img": "i/n1.jpg",
   "thumb": "t/n1.jpg",
   "ratio": "9/16",
