   "fileImg": "TNS-Post_ข่าวพลังงาน_691114_1_บสยSolarPlusค้ำ1000ล้าน_4x5_v1.jpg",
   "fb": "☀️ ข่าวพลังงาน | บสย. ออกโครงการ Solar Plus ค้ำสินเชื่อ 1,000 ล้านบาท หนุนผู้รับเหมาโซลาร์\n\nบรรษัทประกันสินเชื่ออุตสาหกรรมขนาดย่อม (บสย.) ออกโครงการ \"บสย. SMEs โซลาร์พลัส\" ค้ำประกันสินเชื่อให้ SMEs ผู้รับเหมาติดตั้งโซลาร์ภาคประชาชน\n💰 วงเงินโครงการ 1,000 ล้านบาท ค้ำประกันสูงสุด 40 ล้านบาทต่อราย ระยะเวลาค้ำประกัน 7 ปี\n🆓 ฟรีค่าธรรมเนียม 3 ปีแรก ปีที่ 4–7 คิด 1% ต่อปี\n📄 ใช้ขอหนังสือค้ำประกันจากธนาคาร (BG) เบิกใช้ได้ตามสัญญาแต่ละงาน และค้ำสินเชื่อเงินทุนหมุนเวียน เช่น ซื้อแผงโซลาร์และอุปกรณ์\n📊 ผลงาน บสย. ม.ค.–ต.ค. 2569 ค้ำประกันแล้ว 58,037 ล้านบาท ช่วย SMEs เข้าถึงสินเชื่อ 61,712 ราย\n\n💡 ก่อนติดตั้ง เช็กรายชื่อผู้รับจ้างที่ขึ้นทะเบียนกับการไฟฟ้า และขอรายละเอียดอุปกรณ์กับสัญญาให้ชัดเจน\nTNS Solar เป็นผู้รับจ้างขึ้นทะเบียน กฟน. P00639 · กฟภ. P00479\nที่มา: ไทยโพสต์ · ThaiPublica (13 พ.ย. 2569)\n\n📩 สอบถามรายละเอียด / ขอใบเสนอราคา\nLINE: @tnssolar\n☎️ 081 796 4999 (กทม. · นนทบุรี · สมุทรปราการ)\n☎️ 065 295 5998 (ชลบุรี · ภาคกลาง · อีสาน)\n☎️ 087 304 3724 (เชียงใหม่ · ภาคเหนือ)\n🌐 tnsnetwork\n📍 สาขา เชียงใหม่ | ชลบุรี | กรุงเทพมหานคร\n\n#ข่าวพลังงาน #โซลาร์ภาคประชาชน #โซลาร์รูฟท็อป #โซลาร์เซลล์ #SMEs #TNSSolar",
   "tt": "บสย. ค้ำสินเชื่อ 1,000 ล้าน หนุนผู้รับเหมาโซลาร์ภาคประชาชน ☀️ เลือกผู้ติดตั้งที่ขึ้นทะเบียนการไฟฟ้า ปรึกษา LINE @tnssolar\n#ข่าวพลังงาน #โซลาร์ภาคประชาชน #โซลาร์เซลล์ #TNSSolar"
