  "desc": "รายงานข่าวพลังงานประจำวัน: EGCO ลงนามขายไฟโซลาร์ฟาร์ม 11 โครงการ 448 MW · MEA เปิด 4 แนวทางพลังงานสะอาด ชูรถจ่ายไฟแบตเตอรี่ 422 kWh · IEA ชี้ผู้ผลิตโซลาร์รายใหญ่ของจีนกว่า 90% ขาดทุน (ตัวเลขทุกตัวอ้างอิงแหล่งข่าวในคลิปและแคปชั่น)",
  "base": "c/news-691112/",
