  "desc": "คลิปพากย์เสียง + ภาพ 3 ภาพ: แบตเตอรี่โซลาร์ 7 kWh ใช้ได้จริงราว 6 kWh เปิดแอร์ ตู้เย็น ทีวี ไฟ พัดลม และเครื่องใช้ไฟแรงได้นานเท่าไร พร้อมสูตรคิดเอง (6,000 ÷ วัตต์) และตัวอย่างใช้จริง 1 คืน (ตัวเลขเป็นค่าประมาณ)",
  "base": "c/battery7/",
