    "fb": "🔋 แบตเตอรี่โซลาร์ 7 kWh ใช้ไฟอะไรได้กี่ชั่วโมง?\n\nแบต 7 kWh ใช้งานได้จริงประมาณ 6 kWh (6 หน่วย) เพราะต้องเผื่อการคายประจุ (DoD ~90%) และการสูญเสียในอินเวอร์เตอร์ (~95%)\n🧮 สูตรง่าย ๆ: ชั่วโมงที่ใช้ได้ = 6,000 ÷ วัตต์ของเครื่องใช้ไฟฟ้า\n\n❄️ แอร์อินเวอร์เตอร์\n• 9,000 BTU (~600 W) ≈ 10 ชม.\n• 12,000 BTU (~850 W) ≈ 7 ชม.\n• 18,000 BTU (~1,400 W) ≈ 4 ชม.\n\n🏠 เครื่องใช้ประจำบ้าน\n• ตู้เย็น 2 ประตู (~1.2 หน่วย/วัน) ≈ 5 วัน\n• ทีวี LED 55\" (~100 W) ≈ 60 ชม.\n• ไฟ LED 10 ดวง (รวม ~100 W) ≈ 60 ชม.\n• พัดลม (~50 W) ≈ 120 ชม.\n\n⚡ เครื่องใช้ไฟแรง (ใช้ทีละเครื่อง)\n• เครื่องทำน้ำอุ่น 3,500 W ≈ 100 นาที (อาบได้ ~6 ครั้ง)\n• กาต้มน้ำ 1,800 W ≈ 3 ชม. 20 นาที\n• ไมโครเวฟ 1,200 W ≈ 5 ชม.\n• เตารีด 1,000 W ≈ 6 ชม.\n• หม้อหุงข้าว 700 W ≈ 8.5 ชม.\n• ปั๊มน้ำ 250 W ≈ 24 ชม.\n\n🌙 ใช้จริง 1 คืน (18:00–06:00): แอร์ 12,000 BTU 5 ชม. + ตู้เย็น + ไฟ + ทีวี + พัดลม/Wi-Fi รวม ≈ 6 หน่วย พอดีแบต 7 kWh แล้วกลางวันแผงโซลาร์ก็ชาร์จแบตกลับมาเต็ม ☀️\n\n⚠️ เปิดหลายเครื่องพร้อมกัน วัตต์รวมต้องไม่เกินกำลังจ่ายสูงสุดของอินเวอร์เตอร์\n\nอยากรู้ว่าบ้านคุณควรใช้แบตกี่ kWh ส่งบิลค่าไฟมาให้ทีม TNS Solar ช่วยคำนวณได้เลยครับ\nTNS Solar เป็นผู้รับจ้างขึ้นทะเบียน กฟน. P00639 · กฟภ. P00479\n\n📩 สอบถามรายละเอียด / ขอใบเสนอราคา\nLINE: @tnssolar\n☎️ 081 796 4999 (กทม. · นนทบุรี · สมุทรปราการ)\n☎️ 065 295 5998 (ชลบุรี · ภาคกลาง · อีสาน)\n☎️ 087 304 3724 (เชียงใหม่ · ภาคเหนือ)\n🌐 tnsnetwork\n📍 สาขา เชียงใหม่ | ชลบุรี | กรุงเทพมหานคร\n\n*ค่าประมาณ แบต 7 kWh ใช้ได้จริง ~6 kWh (DoD 90%, อินเวอร์เตอร์ ~95%) คิดจากกำลังไฟเฉลี่ยขณะใช้งาน ผลจริงขึ้นกับรุ่น อุณหภูมิ และการตั้งค่า\n\n#แบตเตอรี่โซลาร์ #โซลาร์เซลล์ #ไฮบริด #กักเก็บพลังงาน #ลดค่าไฟ #TNSSolar",
    "tt": "แบตโซลาร์ 7 kWh เปิดแอร์ 12,000 BTU ได้ ~7 ชม. ตู้เย็น ~5 วัน 🔋 สูตรคิดเอง: 6,000 ÷ วัตต์ อยากให้ช่วยคำนวณแบตสำหรับบ้านคุณ ทัก LINE @tnssolar\n*ค่าประมาณ ผลจริงขึ้นกับรุ่นและการใช้งาน\n#แบตเตอรี่โซลาร์ #โซลาร์เซลล์ #ลดค่าไฟ #ไฮบริด #TNSSolar"
