    "title": "ส.อ.ท. เสนอใช้ DPP ติดตามแผงโซลาร์และแบตเตอรี่ใช้แล้ว",
    "video": "v/n1.mp4",
    "poster": "p/n1.jpg",
    "file": "TNS-News_691111_1_VO.mp4",
    "img": "i/n1.jpg",
    "thumb": "t/n1.jpg",
    "ratio": "9/16",
    "imgRatio": "1080/1350",
    "fileImg": "TNS-Post_ข่าวพลังงาน_691111_1_ติดตามแผงโซลาร์แบตใช้แล้ว_4x5_v1.jpg",
    "fb": "☀️ ข่าวพลังงาน | เอกชนเสนอระบบติดตามแผงโซลาร์-แบตเตอรี่ใช้แล้ว\n\nสภาอุตสาหกรรมแห่งประเทศไทย (ส.อ.ท.) สนับสนุนให้รัฐพัฒนาระบบตรวจสอบย้อนกลับกากอุตสาหกรรม และเสนอแนวคิด Digital Product Passport (DPP) ร่วมกับ GS1 Thailand เพื่อติดตามข้อมูลแบตเตอรี่และแผงโซลาร์เซลล์ใช้แล้ว\n☀️ ไทยมีโรงไฟฟ้าแสงอาทิตย์ราว 15,000 MW คิดเป็นแผงราว 42 ล้านแผง\n🏠 โครงการโซลาร์ภาคประชาชน 1 ล้านครัวเรือน คาดว่าจะใช้แผงเพิ่มอีกราว 7–8 ล้านแผง\n⏳ แผงโซลาร์มีอายุใช้งานราว 20–25 ปี จึงต้องวางระบบจัดการแผงหมดอายุตั้งแต่วันนี้\n🔎 ข้อเสนอ: ตรวจสอบย้อนกลับตลอดห่วงโซ่ ตั้งแต่ผู้ก่อกำเนิด ผู้ขนส่ง ถึงผู้รับจัดการ และอาจเริ่มจากโครงการนำร่อง\n\n💡 สำหรับบ้านที่ติดโซลาร์: เก็บข้อมูลรุ่นอุปกรณ์และใบรับประกันไว้ เลือกอุปกรณ์ได้มาตรฐานที่มีตัวแทนดูแลในประเทศ และตรวจเช็กระบบตามรอบ\nTNS Solar เป็นผู้รับจ้างขึ้นทะเบียน กฟน. P00639 · กฟภ. P00479\nที่มา: ส.อ.ท. ผ่านผู้จัดการออนไลน์ (11 พ.ย. 2569)\n\n📩 สอบถามรายละเอียด / ขอใบเสนอราคา\nLINE: @tnssolar\n☎️ 081 796 4999 (กทม. · นนทบุรี · สมุทรปราการ)\n☎️ 065 295 5998 (ชลบุรี · ภาคกลาง · อีสาน)\n☎️ 087 304 3724 (เชียงใหม่ · ภาคเหนือ)\n🌐 tnsnetwork\n📍 สาขา เชียงใหม่ | ชลบุรี | กรุงเทพมหานคร\n\n#ข่าวพลังงาน #แผงโซลาร์ #แบตเตอรี่ #รีไซเคิล #โซลาร์เซลล์ #TNSSolar",
