    "title": "โซลาร์ภาคประชาชน บ้านแบบไหนติดแล้วคุ้ม",
    "video": "v/n1.mp4",
    "poster": "p/n1.jpg",
    "file": "TNS-News_691108_1_VO_v2.mp4",
    "img": "i/n1.jpg",
