    "fileImg": "TNS-Post_ข่าวพลังงาน_691108_1_โซลาร์ภาคประชาชนบ้านไหนคุ้ม_4x5_v2.jpg",
    "fb": "☀️ ข่าวพลังงาน | โซลาร์ภาคประชาชน บ้านแบบไหนติดแล้วคุ้ม\n\nกระทรวงการคลัง ธนาคารออมสิน และ ธอส. ชี้แจงโครงการโซลาร์ภาคประชาชน (5 พ.ย. 2569)\n💡 ค่าไฟตั้งแต่ 3,000 บาท/เดือนขึ้นไป เหมาะกับการติดตั้ง · ต่ำกว่า 2,000 บาท/เดือน คืนทุนช้า ไม่แนะนำ\n☀️ ควรใช้ไฟช่วงกลางวันอย่างน้อย 40% เช่น มีผู้สูงอายุอยู่บ้าน ทำงานที่บ้าน ร้านค้า ฟาร์มที่ใช้ปั๊มน้ำ\n🏠 หลังคาหันทิศใต้หรือทิศตะวันตกดีที่สุด ไม่แนะนำทิศเหนือ และโครงสร้างต้องรับน้ำหนักแผงได้\n📊 ตัวอย่างของธนาคารออมสิน: ค่าไฟ 4,000 บาท/เดือน ติด 5 kW ประหยัดค่าไฟ ~1,176 บาท/เดือน + ขายไฟส่วนเกิน ~792 บาท/เดือน (2.20 บาท/หน่วย 20 ปี) หักค่างวด 7 ปีแล้วยังประหยัด ~799 บาท/เดือน ผ่อนหมดแล้ว ~1,968 บาท/เดือน (ประมาณการ ไม่ใช่การรับประกันผล)\n🎯 เป้าหมาย 1 ล้านครัวเรือน รัฐอุดหนุน 50,000 บาท/ครัวเรือน · ลงทะเบียนแล้วไม่ถึง 100,000 ราย (ณ 5 พ.ย.) · ลงทะเบียนได้ถึง 31 ม.ค. 2570\n\n✅ ก่อนลงทะเบียน: ดูบิลค่าไฟย้อนหลัง 12 เดือน ให้ช่างสำรวจหลังคาและทิศแดด และเลือกผู้ติดตั้งที่ขึ้นทะเบียนกับการไฟฟ้า\nTNS Solar เป็นผู้รับจ้างขึ้นทะเบียน กฟน. P00639 · กฟภ. P00479\nที่มา: แถลงกระทรวงการคลัง ธนาคารออมสิน ธอส. 5 พ.ย. 2569 ผ่าน THE STANDARD (7 พ.ย.) และ ThaiPublica\n\n📩 สอบถามรายละเอียด / ขอใบเสนอราคา\nLINE: @tnssolar\n☎️ 081 796 4999 (กทม. · นนทบุรี · สมุทรปราการ)\n☎️ 065 295 5998 (ชลบุรี · ภาคกลาง · อีสาน)\n☎️ 087 304 3724 (เชียงใหม่ · ภาคเหนือ)\n🌐 tnsnetwork\n📍 สาขา เชียงใหม่ | ชลบุรี | กรุงเทพมหานคร\n\n#ข่าวพลังงาน #โซลาร์ภาคประชาชน #โซลาร์รูฟท็อป #ค่าไฟ #โซลาร์เซลล์ #TNSSolar",
    "tt": "โซลาร์ภาคประชาชน บ้านแบบไหนติดแล้วคุ้ม? ค่าไฟ 3,000+ บาท ใช้ไฟกลางวัน 40%+ ☀️ ให้ TNS สำรวจหลังคา ทัก LINE @tnssolar\n#ข่าวพลังงาน #โซลาร์ภาคประชาชน #โซลาร์เซลล์ #TNSSolar"
