    "label": "02",
    "title": "IEA คาดอินเดียมีโซลาร์เกิน 350 GW ในปี 2030",
    "video": "v/n2.mp4",
    "poster": "p/n2.jpg",
    "file": "TNS-News_691108_2_VO_v2.mp4",
    "img": "i/n2.jpg",
    "thumb": "t/n2.jpg",
    "ratio": "9/16",
    "imgRatio": "1080/1350",
    "fileImg": "TNS-Post_ข่าวพลังงาน_691108_2_IEAอินเดียโซลาร์350GW_4x5_v2.jpg",
    "fb": "☀️ ข่าวพลังงาน | IEA คาดอินเดียมีโซลาร์เกิน 350 GW ในปี 2030\n\nทบวงพลังงานระหว่างประเทศ (IEA) เผยแพร่รายงาน India Renewable Energy Market Report 2026\n🇮🇳 พลังงานหมุนเวียนอินเดียวันนี้เกิน 300 GW เพิ่มเกือบ 4 เท่าในราว 10 ปี · ปี 2025 ติดตั้งเพิ่ม 49 GW\n☀️ ปี 2030 คาดโซลาร์เกิน 350 GW (ราว 2.5 เท่า) · พลังงานหมุนเวียนรวมราว 530 GW · ลมเกือบ 90 GW\n⚡ ผลิตไฟฟ้าจากพลังงานหมุนเวียนราว 950 TWh หรือราว 35% ของประเทศ (จากราว 500 TWh ในปี 2025)\n🏠 โซลาร์ติดตั้งเพื่อใช้เอง (หลังคาบ้าน อาคาร ภาคเกษตร) คาดเพิ่ม 3 เท่า เป็นกว่า 100 GW แรงหนุนจาก PM Surya Ghar และ PM-KUSUM\n\n💡 โซลาร์เพื่อใช้เองกำลังโตทั่วโลก เหมาะทั้งบ้านที่ใช้ไฟกลางวันมาก โรงงาน อาคารพาณิชย์ และปั๊มน้ำภาคเกษตร\nที่มา: IEA ผ่าน pv magazine India และ Power Peak Digest 5 พ.ย. 2569 · ตัวเลขปี 2030 เป็นค่าคาดการณ์\n\n📩 สอบถามรายละเอียด / ขอใบเสนอราคา\nLINE: @tnssolar\n☎️ 081 796 4999 (กทม. · นนทบุรี · สมุทรปราการ)\n☎️ 065 295 5998 (ชลบุรี · ภาคกลาง · อีสาน)\n☎️ 087 304 3724 (เชียงใหม่ · ภาคเหนือ)\n🌐 tnsnetwork\n📍 สาขา เชียงใหม่ | ชลบุรี | กรุงเทพมหานคร\n\n#ข่าวพลังงาน #โซลาร์เซลล์ #พลังงานหมุนเวียน #IEA #พลังงานสะอาด #TNSSolar",
    "tt": "IEA คาดอินเดียมีโซลาร์เกิน 350 GW ปี 2030 🌏 โซลาร์ใช้เองโต 3 เท่า บ้านคุณก็เริ่มได้ ทัก LINE @tnssolar\n#ข่าวพลังงาน #โซลาร์เซลล์ #พลังงานหมุนเวียน #TNSSolar"
