    "fileImg": "TNS-Post_ข่าวพลังงาน_691107_2_แบตโซเดียมไอออนใกล้LFP_4x5_v2.jpg",
    "fb": "☀️ ข่าวพลังงาน | แบตเตอรี่โซเดียมไอออน ต้นทุนใกล้เท่า LFP\n\nWood Mackenzie ศึกษาตลาดจีน สหรัฐฯ เยอรมนี และอินเดีย (เผยแพร่ 6 พ.ย. 2569)\n🔋 ราคาเฉลี่ยโซเดียมไอออนราว 229 ดอลลาร์/kWh เทียบ LFP ราว 200 ดอลลาร์/kWh\n📅 ต้นทุนระดับเซลล์คาดเท่า LFP ปลายปี 2026 · ระดับระบบทั้งชุดคาดหลังปี 2030\n📝 สัญญาซื้อขายแล้วกว่า 70 GWh ทั่วโลก\n🏭 BYD วางแผนกำลังผลิต 30 GWh · CATL ตั้งเป้าส่งมอบเกิน 1 GWh ภายในสิ้นปี 2026\n📉 ประมาณการต้นทุนตลอดอายุโครงการ 20 ปี ต่ำกว่า LFP ราว 21%\n\n💡 แบตเตอรี่บ้านวันนี้: รายงานระบุว่า LFP ยังเป็นเทคโนโลยีที่พร้อมใช้ที่สุดสำหรับระบบ 2–4 ชั่วโมง เลือกโดยดูการรับประกัน จำนวนรอบชาร์จ และเช็กว่าอินเวอร์เตอร์รองรับ (Hybrid)\nที่มา: Wood Mackenzie ผ่าน ESS News (pv magazine) 6 พ.ย. 2569 · ตัวเลขเป็นค่าประมาณการ\n\n📩 สอบถามรายละเอียด / ขอใบเสนอราคา\nLINE: @tnssolar\n☎️ 081 796 4999 (กทม. · นนทบุรี · สมุทรปราการ)\n☎️ 065 295 5998 (ชลบุรี · ภาคกลาง · อีสาน)\n☎️ 087 304 3724 (เชียงใหม่ · ภาคเหนือ)\n🌐 tnsnetwork\n📍 สาขา เชียงใหม่ | ชลบุรี | กรุงเทพมหานคร\n\n#ข่าวพลังงาน #แบตเตอรี่ #โซเดียมไอออน #โซลาร์เซลล์ #พลังงานสะอาด #TNSSolar",
