    "fileImg": "TNS-Post_ข่าวพลังงาน_691107_3_จีนโซลาร์ลมทะเลทราย157GW_4x5_v2.jpg",
    "fb": "☀️ ข่าวพลังงาน | จีนสร้างโซลาร์ + ลมในทะเลทรายเกิน 157 GW\n\nสำนักงานพลังงานแห่งชาติจีน (NEA) รายงานข้อมูล ณ สิ้น ก.ย. 2026\n☀️ โซลาร์และพลังงานลมในพื้นที่ทะเลทรายและโกบี สร้างแล้วกว่า 157 GW\n1️⃣ ชุดที่ 1: 94.53 GW เกือบแล้วเสร็จทั้งหมด\n2️⃣ ชุดที่ 2: สร้างแล้วกว่า 34 GW\n3️⃣ ชุดที่ 3: สร้างแล้วกว่า 29 GW (ทั้ง 3 ชุดประกาศระหว่างปี 2021–2023)\n🏗️ อนุมัติฐานพลังงานขนาดราว 10 GW ขึ้นไปอีก 14 แห่ง เน้นส่งไฟข้ามภูมิภาค เดินเครื่องแล้ว 2 แห่ง (เทียนซานเหนือ ซินเจียง · ทะเลทรายเทงเกอร์ หนิงเซี่ย)\n\n💡 โซลาร์ฟาร์มใหญ่ต้องมีสายส่งไฟระยะไกล ส่วนโซลาร์บนหลังคาผลิตไฟ ณ จุดใช้งาน ไทยแดดดีเกือบทั้งปี 1 kW ผลิตไฟได้ราว 4 หน่วยต่อวัน (ค่าประมาณ)\nที่มา: NEA ผ่าน TaiyangNews 6 พ.ย. 2569\n\n📩 สอบถามรายละเอียด / ขอใบเสนอราคา\nLINE: @tnssolar\n☎️ 081 796 4999 (กทม. · นนทบุรี · สมุทรปราการ)\n☎️ 065 295 5998 (ชลบุรี · ภาคกลาง · อีสาน)\n☎️ 087 304 3724 (เชียงใหม่ · ภาคเหนือ)\n🌐 tnsnetwork\n📍 สาขา เชียงใหม่ | ชลบุรี | กรุงเทพมหานคร\n\n#ข่าวพลังงาน #โซลาร์ฟาร์ม #พลังงานหมุนเวียน #โซลาร์เซลล์ #TNSSolar",
