    "fileImg": "TNS-Post_ข่าวพลังงาน_691106_1_GPSCโซลาร์ฟาร์มโคราช148MW_4x5_v2.jpg",
    "fb": "☀️ ข่าวพลังงาน | GPSC เริ่มสร้างโซลาร์ฟาร์ม 148 MW ที่โคราช\n\nGPSC จัดพิธีบวงสรวงเริ่มก่อสร้างโครงการ Helios 1 และ Helios 2 ที่ ต.พลกรัง อ.เมืองนครราชสีมา (5 พ.ย. 2569)\n☀️ ขนาดแผงรวมราว 148 MWp ติดตั้งบนพื้นดิน — Helios 1 แผงหมุนตามแดด (Tracking) · Helios 2 แผงยึดอยู่กับที่ (Fixed)\n⚡ กำลังผลิตตามสัญญารวม 110 MW ขายไฟให้ กฟผ. สัญญา 25 ปี ภายใต้โครงการรับซื้อไฟฟ้าพลังงานหมุนเวียน (FiT) ปี 2565–2573\n🔌 คาดผลิตไฟรวมราว 252 ล้านหน่วยต่อปี\n📅 กำหนดจ่ายไฟเชิงพาณิชย์ภายใน มิ.ย. 2571 · ก่อสร้างโดยกิจการร่วมค้า Getz AKK\n\n💡 บ้านทั่วไปใช้แผงแบบยึดบนหลังคา เลือกทิศและมุมเอียงให้รับแดดดีที่สุด\nTNS Solar เป็นผู้รับจ้างขึ้นทะเบียน กฟน. P00639 · กฟภ. P00479\nที่มา: กรุงเทพธุรกิจ 6 พ.ย. 2569, ฐานเศรษฐกิจ 25 ก.ย. 2569\n\n📩 สอบถามรายละเอียด / ขอใบเสนอราคา\nLINE: @tnssolar\n☎️ 081 796 4999 (กทม. · นนทบุรี · สมุทรปราการ)\n☎️ 065 295 5998 (ชลบุรี · ภาคกลาง · อีสาน)\n☎️ 087 304 3724 (เชียงใหม่ · ภาคเหนือ)\n🌐 tnsnetwork\n📍 สาขา เชียงใหม่ | ชลบุรี | กรุงเทพมหานคร\n\n#ข่าวพลังงาน #โซลาร์ฟาร์ม #โซลาร์เซลล์ #พลังงานสะอาด #TNSSolar #นครราชสีมา",
    "tt": "GPSC เริ่มสร้างโซลาร์ฟาร์ม 148 MW ที่โคราช ขายไฟให้ กฟผ. 25 ปี ☀️ อยากติดโซลาร์ที่บ้าน ถาม LINE @tnssolar\n#ข่าวพลังงาน #โซลาร์ฟาร์ม #โซลาร์เซลล์ #TNSSolar"
