    "fileImg": "TNS-Post_ข่าวพลังงาน_691106_2_ตุรกีเป้าโซลาร์ลม175GW_4x5_v2.jpg",
    "fb": "☀️ ข่าวพลังงาน | ตุรกีตั้งเป้าโซลาร์ + ลม 175 GW ในปี 2040\n\nรมว.พลังงานตุรกี Alparslan Bayraktar เปิดแผน \"National Energy 2040\" ที่อิสตันบูล (5 พ.ย. 2569)\n☀️ กำลังผลิตจากแสงอาทิตย์และลม จากราว 45 GW เป็น 175 GW ภายในปี 2040 ลงทุนราว 1 แสนล้านดอลลาร์สหรัฐ\n📈 กำลังผลิตติดตั้งรวม 123 GW (ปี 2025) → 281 GW (ปี 2040)\n🌱 สัดส่วนพลังงานหมุนเวียน 63% → 77% ของกำลังผลิตติดตั้ง\n🌬️ ลมนอกชายฝั่ง 6 GW เปิดประมูลครั้งแรก เม.ย. ปีหน้า\n💻 ความต้องการไฟปี 2040 ราว 680 TWh รวมดาต้าเซ็นเตอร์ราว 55 TWh\n\n💡 ไทยมีแดดแรงเกือบทั้งปี โซลาร์รูฟท็อปช่วยผลิตไฟใช้เองตอนกลางวัน ลดหน่วยไฟที่ต้องซื้อ\nที่มา: Daily Sabah, Hürriyet Daily News 5 พ.ย. 2569\n\n📩 สอบถามรายละเอียด / ขอใบเสนอราคา\nLINE: @tnssolar\n☎️ 081 796 4999 (กทม. · นนทบุรี · สมุทรปราการ)\n☎️ 065 295 5998 (ชลบุรี · ภาคกลาง · อีสาน)\n☎️ 087 304 3724 (เชียงใหม่ · ภาคเหนือ)\n🌐 tnsnetwork\n📍 สาขา เชียงใหม่ | ชลบุรี | กรุงเทพมหานคร\n\n#ข่าวพลังงาน #พลังงานหมุนเวียน #โซลาร์เซลล์ #พลังงานสะอาด #TNSSolar",
