    "fb": "☀️ ข่าวพลังงาน | บ้านโซลาร์ในสหรัฐฯ 75% ติดแบตเตอรี่ด้วย\n\nSunrun ผู้ให้บริการโซลาร์บ้านรายใหญ่ของสหรัฐฯ รายงานผลไตรมาส 3 ปี 2026 (4 พ.ย. 2569)\n🔋 ลูกค้าใหม่ 75% ติดแบตเตอรี่คู่โซลาร์ (ปีก่อน 70%) — 18,081 จาก 24,096 ราย\n⚡ แบตเตอรี่บ้านที่เชื่อมเครือข่ายรวม 5,022 MWh (ราว 5 GWh) ณ 30 ก.ย. 2026\n🏠 โรงไฟฟ้าเสมือน (VPP): รวมแบตเตอรี่หลายบ้านจ่ายไฟพร้อมกันกว่า 430 MW (6 ต.ค. 2026) ช่วยระบบไฟฟ้าช่วงความต้องการสูง\n👥 ลูกค้ารวมราว 1.23 ล้านราย\n\n💡 ก่อนเพิ่มแบตเตอรี่ให้บ้าน: ดูการใช้ไฟช่วงเย็นถึงกลางคืนเพื่อเลือกขนาด เช็กว่าอินเวอร์เตอร์รองรับ (Hybrid) และถ้าต้องการสำรองไฟตอนไฟดับ เลือกระบบที่มี Back-up\nที่มา: Sunrun Q3 2026 Financial Results (GlobeNewswire 4 พ.ย. 2569)\n\n📩 สอบถามรายละเอียด / ขอใบเสนอราคา\nLINE: @tnssolar\n☎️ 081 796 4999 (กทม. · นนทบุรี · สมุทรปราการ)\n☎️ 065 295 5998 (ชลบุรี · ภาคกลาง · อีสาน)\n☎️ 087 304 3724 (เชียงใหม่ · ภาคเหนือ)\n🌐 tnsnetwork\n📍 สาขา เชียงใหม่ | ชลบุรี | กรุงเทพมหานคร\n\n#ข่าวพลังงาน #แบตเตอรี่ #โซลาร์เซลล์ #พลังงานสะอาด #TNSSolar",
