  "desc": "รายงานข่าวพลังงานประจำวัน: ก.พลังงานกางโรดแมป ไฟฟ้าสะอาด 50% ใน 10 ปี · มาเลเซียโซลาร์ 500 MW + แบตเตอรี่ 1 GWh · เวียดนามอนุมัติโซลาร์ลอยน้ำ 452 MW (ตัวเลขทุกตัวอ้างอิงแหล่งข่าวในภาพและแคปชั่น)",
