    "fb": "☀️ ข่าวพลังงาน | กระทรวงพลังงานกางโรดแมป ไฟฟ้าสะอาด 50% ใน 10 ปี\n\nรมว.พลังงาน กล่าวบนเวที THE STANDARD Economic Forum 2026 (4 พ.ย. 2569) สรุปสาระสำคัญ:\n🌱 แผน PDP ใหม่ เพิ่มสัดส่วนไฟฟ้าสะอาดจากราว 20% เป็น 50% ภายใน 10 ปี และเกิน 65% ในระยะถัดไป\n☀️ โซลาร์รูฟท็อป: ขยายโควตารับซื้อเป็น 10,000 MW ราคา 2.20 บาท/หน่วย สัญญา 20 ปี ใช้ค่าไฟในอนาคตเป็นหลักประกันช่วยเรื่องเงินลงทุน\n🏭 Direct PPA: ขยายจาก Sandbox ดาต้าเซ็นเตอร์ (2,000 MW) สู่ทุกอุตสาหกรรม ค่าใช้สายส่งเบื้องต้นราว 1.40 บาท/หน่วย รอ กกพ. กำหนด\n💻 ดาต้าเซ็นเตอร์: จัดเป็นผู้ใช้ไฟประเภทใหม่ รับต้นทุน LNG นำเข้าเอง — กระทรวงระบุว่าค่าไฟบ้านจะไม่ถูกปรับขึ้นเพื่อการนี้\n\n💡 วางแผนติดโซลาร์: เช็กหลังคาและทิศแดด ดูบิลค่าไฟย้อนหลังเพื่อเลือกขนาดระบบ และเลือกผู้รับจ้างที่ขึ้นทะเบียนกับการไฟฟ้า\nTNS Solar เป็นผู้รับจ้างขึ้นทะเบียน กฟน. P00639 · กฟภ. P00479\nที่มา: THE STANDARD 4 พ.ย. 2569, ประชาไท 5 พ.ย. 2569\n\n📩 สอบถามรายละเอียด / ขอใบเสนอราคา\nLINE: @tnssolar\n☎️ 081 796 4999 (กทม. · นนทบุรี · สมุทรปราการ)\n☎️ 065 295 5998 (ชลบุรี · ภาคกลาง · อีสาน)\n☎️ 087 304 3724 (เชียงใหม่ · ภาคเหนือ)\n🌐 tnsnetwork\n📍 สาขา เชียงใหม่ | ชลบุรี | กรุงเทพมหานคร\n\n#ข่าวพลังงาน #โซลาร์รูฟท็อป #โซลาร์เซลล์ #พลังงานสะอาด #TNSSolar #PDP",
