    "fb": "☀️ ข่าวพลังงาน | มาเลเซียสร้างโซลาร์ 500 MW พร้อมแบตเตอรี่ 1 GWh\n\nIOI Corporation ร่วมกับ TNB (การไฟฟ้ามาเลเซีย) พัฒนาโซลาร์ฟาร์มที่ Bahau รัฐเนกรีเซมบีลัน\n⚡ โซลาร์ 500 MWac บนพื้นที่ราว 1,300 เอเคอร์ (ราว 3,300 ไร่)\n🔋 แบตเตอรี่ 250 MW / 1,000 MWh (1 GWh)\n💻 ผู้ซื้อไฟ: DayOne ผู้ให้บริการดาต้าเซ็นเตอร์ สัญญา 21 ปี ภายใต้โครงการ CRESS\n📅 ตามเงื่อนไข CRESS ฉบับปรับปรุง โครงการต้องเปิดใช้ภายในสิ้นปี 2028 เพื่อรับค่าใช้ระบบอัตราพิเศษ\n\n💡 บ้านที่ติดโซลาร์: แบตเตอรี่เก็บไฟส่วนเกินตอนกลางวันไว้ใช้ช่วงเย็น และสำรองไฟตอนไฟดับได้ในระบบที่รองรับ\nที่มา: ESS News / pv magazine 4 พ.ย. 2569, SMM 5 พ.ย. 2569\n\n📩 สอบถามรายละเอียด / ขอใบเสนอราคา\nLINE: @tnssolar\n☎️ 081 796 4999 (กทม. · นนทบุรี · สมุทรปราการ)\n☎️ 065 295 5998 (ชลบุรี · ภาคกลาง · อีสาน)\n☎️ 087 304 3724 (เชียงใหม่ · ภาคเหนือ)\n🌐 tnsnetwork\n📍 สาขา เชียงใหม่ | ชลบุรี | กรุงเทพมหานคร\n\n#ข่าวพลังงาน #แบตเตอรี่ #โซลาร์เซลล์ #พลังงานสะอาด #TNSSolar",
