    "fb": "☀️ ข่าวพลังงาน | เวียดนามอนุมัติโซลาร์ลอยน้ำ 452 MW\n\nจังหวัดดั๊กลัก อนุมัติโครงการโซลาร์ลอยน้ำบนอ่างเก็บน้ำ Ea Sup Thuong (31 ต.ค. 2569)\n💰 มูลค่าลงทุนราว 355 ล้านดอลลาร์สหรัฐ (ราว 9.15 ล้านล้านดอง) โดยกลุ่มบริษัทเวียดนาม 4 ราย\n💧 แผงลอยบนผิวน้ำราว 523 เฮกตาร์\n🔋 มีระบบแบตเตอรี่กักเก็บพลังงาน (ยังไม่เปิดเผยขนาด)\n⚡ สายส่ง 220 kV ยาว 6 กม. เชื่อมเข้าระบบไฟฟ้าประเทศ\n📅 เปิดดำเนินการเชิงพาณิชย์ไม่เกินไตรมาส 4 ปี 2028 · ระยะเวลาโครงการ 50 ปี\n\n💡 โซลาร์ลอยน้ำใช้ผิวน้ำแทนที่ดิน ส่วนบ้านทั่วไปใช้พื้นที่หลังคาติดโซลาร์รูฟท็อปได้เลย\nที่มา: SolarQuarter / IndexBox / pv magazine 4 พ.ย. 2569\n\n📩 สอบถามรายละเอียด / ขอใบเสนอราคา\nLINE: @tnssolar\n☎️ 081 796 4999 (กทม. · นนทบุรี · สมุทรปราการ)\n☎️ 065 295 5998 (ชลบุรี · ภาคกลาง · อีสาน)\n☎️ 087 304 3724 (เชียงใหม่ · ภาคเหนือ)\n🌐 tnsnetwork\n📍 สาขา เชียงใหม่ | ชลบุรี | กรุงเทพมหานคร\n\n#ข่าวพลังงาน #โซลาร์ลอยน้ำ #โซลาร์เซลล์ #พลังงานสะอาด #TNSSolar",
