    "fb": "☀️ ข่าวพลังงาน | โซลาร์ภาคประชาชน ลงทะเบียนแล้ว 42,666 ราย\n\nกฟภ. รายงานว่า ตั้งแต่เปิดรับสมัคร 27 ต.ค. – 2 พ.ย. 2569 มีผู้ลงทะเบียนสำเร็จในเขต กฟภ. แล้ว 42,666 ราย\n\n✅ เงินสนับสนุนค่าติดตั้ง 50,000 บาท/ครัวเรือน (ใช้สิทธิ์ได้ 1 ครั้ง)\n✅ ขายไฟส่วนเกินคืน 2.20 บาท/หน่วย นาน 20 ปี (ไม่เกิน 5 kW ต่อมิเตอร์)\n✅ เป้าหมาย 1 ล้านครัวเรือน\n\n⚠️ ข้อควรรู้: ใช้ควบคู่กับสิทธิ์ลดหย่อนภาษีค่าติดตั้งโซลาร์ไม่ได้\n📝 ต่างจังหวัดสมัครที่ peoplesolar.pea.co.th · กทม. นนทบุรี สมุทรปราการ สมัครผ่าน กฟน.\n\nกรณีเอกสารสำรวจผู้ประกอบการภาคเหนือ กฟภ. ชี้แจงว่าเป็นเอกสารภายในที่ยังไม่ได้รับความเห็นชอบ ยกเลิกแล้ว และตั้งคณะกรรมการสอบข้อเท็จจริง\n\nTNS Solar เป็นผู้รับจ้างขึ้นทะเบียน กฟน. P00639 · กฟภ. P00479\nที่มา: แถลงข่าว กฟภ./กฟน. 2 พ.ย. 2569\n\n📩 สอบถามรายละเอียด / ขอใบเสนอราคา\nLINE: @tnssolar\n☎️ 081 796 4999 (กทม. · นนทบุรี · สมุทรปราการ)\n☎️ 065 295 5998 (ชลบุรี · ภาคกลาง · อีสาน)\n☎️ 087 304 3724 (เชียงใหม่ · ภาคเหนือ)\n🌐 tnsnetwork\n📍 สาขา เชียงใหม่ | ชลบุรี | กรุงเทพมหานคร\n\n#โซลาร์ภาคประชาชน #โซลาร์เซลล์ #ข่าวพลังงาน #ติดโซลาร์ #TNSSolar #โซลาร์รูฟท็อป",
