    "fb": "☀️ ข่าวพลังงาน | จีนออกมาตรฐานบังคับแผงโซลาร์ฉบับแรก\n\nจีนประกาศมาตรฐานระดับชาติแบบบังคับ 2 ฉบับที่เขียนเพื่อแผงโซลาร์โดยเฉพาะ (ประกาศ 25 พ.ค. 2569 มีผล 1 มิ.ย. 2570)\n\n🛡️ GB 47739-2026 ความปลอดภัยของแผง: ไฟฟ้า · ความแข็งแรง · การป้องกันไฟ · สารอันตราย · ความทนทานต่อ Hot Spot\n🏷️ GB 47740-2026 ป้ายข้อมูลแผง: ข้อมูลครบถ้วน · เก็บรักษาข้อมูล · ตรวจสอบย้อนกลับค่าที่วัดได้\n\nล่าสุด 11 ผู้ผลิตได้รับใบรับรองชุดแรก เช่น LONGi, JinkoSolar, Trina, JA, Tongwei, AIKO\n\n💡 เลือกแผงโซลาร์: ดูป้ายข้อมูลที่ครบ ใบรับรองมาตรฐาน และเงื่อนไขรับประกันทั้งสินค้าและกำลังผลิต\nที่มา: TaiyangNews 3 พ.ย. 2569\n\n📩 สอบถามรายละเอียด / ขอใบเสนอราคา\nLINE: @tnssolar\n☎️ 081 796 4999 (กทม. · นนทบุรี · สมุทรปราการ)\n☎️ 065 295 5998 (ชลบุรี · ภาคกลาง · อีสาน)\n☎️ 087 304 3724 (เชียงใหม่ · ภาคเหนือ)\n🌐 tnsnetwork\n📍 สาขา เชียงใหม่ | ชลบุรี | กรุงเทพมหานคร\n\n#แผงโซลาร์ #โซลาร์เซลล์ #ข่าวพลังงาน #มาตรฐานแผงโซลาร์ #TNSSolar",
