    "fb": "คำนวณขนาดโซลาร์ On-Grid เองได้ใน 4 ขั้น 🧮\n\n1️⃣ ดูบิลค่าไฟย้อนหลัง 12 เดือน แยกการใช้ไฟช่วงกลางวัน (แผงผลิตไฟได้เฉพาะกลางวัน)\n   ตัวอย่าง: 600 หน่วย/เดือน ใช้กลางวัน 50% = 10 หน่วย/วัน\n2️⃣ ขนาดแผง (kWp) = หน่วยกลางวัน/วัน ÷ (PSH × PR)\n   10 ÷ (4.5 × 0.78) ≈ 2.85 kWp → แผง 550 W × 6 แผง = 3.3 kWp\n3️⃣ เลือกอินเวอร์เตอร์ให้ DC/AC ≈ 1.0–1.3 → ใช้ 3 kW (DC/AC = 1.1)\n4️⃣ ผลิตไฟได้ราว 350 หน่วย/เดือน ลดค่าไฟประมาณ 1,400 บาท/เดือน*\n\n⚠️ ระบบ On-Grid ต้องขออนุญาตการไฟฟ้าก่อนติดตั้ง · ไม่ขายไฟคืนติด Zero Export · ใช้ไฟกลางคืนเยอะลองพิจารณา Hybrid\n\nทักมาปรึกษาทีม TNS Solar ได้เลยครับ\n\nLINE: @tnssolar\nโทร (แยกตามพื้นที่ติดตั้ง)\n• 081 796 4999 — กรุงเทพฯ นนทบุรี สมุทรปราการ (กฟน.)\n• 065 295 5998 — ชลบุรี ภาคกลาง ภาคตะวันออกเฉียงเหนือ (กฟภ.)\n• 087 304 3724 — เชียงใหม่ ภาคเหนือ (กฟภ.)\nเว็บไซต์: tnsnetwork\nสาขา: เชียงใหม่ | ชลบุรี | กรุงเทพมหานคร\n\n*ค่าประมาณ PSH 4.5 ชม./วัน PR 0.78 ค่าไฟ ~4 บาท/หน่วย ผลจริงขึ้นกับทิศ มุมหลังคา และเงาบัง\n\n#โซลาร์เซลล์ #คำนวณโซลาร์ #OnGrid #ลดค่าไฟ #เจาะลึกโซลาร์ #TNSSolar",
    "tt": "คำนวณขนาดโซลาร์ On-Grid เองใน 4 ขั้น: ดูบิล → ขนาดแผง → อินเวอร์เตอร์ → ผลผลิต ส่งบิลมาให้ทีม TNS ช่วยคำนวณได้ ทักไลน์ @tnssolar\n*ค่าประมาณ PSH 4.5 ชม./วัน PR 0.78 ค่าไฟ ~4 บาท/หน่วย ผลจริงขึ้นกับทิศ มุมหลังคา และเงาบัง\n#โซลาร์เซลล์ #คำนวณโซลาร์ #OnGrid #ลดค่าไฟ #TNSSolar"
