    "fb": "รวมศัพท์โซลาร์ที่ควรรู้ 📘 คุยกับช่าง อ่านสเปกได้มั่นใจ\n\nประเภทระบบ\n• On-grid — ต่อการไฟฟ้า ไม่มีแบตเตอรี่\n• Hybrid — ต่อการไฟฟ้า + แบตเตอรี่\n• Off-grid — ไม่ต่อการไฟฟ้า ใช้แบตเตอรี่\n• Micro Inverter — แปลงไฟที่แผง ติดใต้แผง\n\nค่าบนสเปกแผง\n• Wp / kWp — กำลังสูงสุดที่สภาวะมาตรฐาน (STC)\n• Voc — แรงดันวงจรเปิด · Isc — กระแสลัดวงจร\n• Vmp / Imp — แรงดันและกระแสที่จุดกำลังสูงสุด\n\nการทำงาน\n• MPPT — ระบบหาจุดกำลังสูงสุด\n• String — แผงต่ออนุกรม เพิ่มแรงดัน\n• PSH — ชั่วโมงแดดพีค ไทยราว 4–5.5 ชม./วัน\n• PR — สัดส่วนผลผลิตจริง ราว 0.7–0.85\n\nอุปกรณ์ป้องกัน: SPD กันไฟกระชาก · DC Switch ตัดวงจร DC · RCD ตัดไฟรั่ว · Grounding ระบบสายดิน\n\nทักมาปรึกษาทีม TNS Solar ได้เลยครับ\n\nLINE: @tnssolar\nโทร (แยกตามพื้นที่ติดตั้ง)\n• 081 796 4999 — กรุงเทพฯ นนทบุรี สมุทรปราการ (กฟน.)\n• 065 295 5998 — ชลบุรี ภาคกลาง ภาคตะวันออกเฉียงเหนือ (กฟภ.)\n• 087 304 3724 — เชียงใหม่ ภาคเหนือ (กฟภ.)\nเว็บไซต์: tnsnetwork\nสาขา: เชียงใหม่ | ชลบุรี | กรุงเทพมหานคร\n\n#โซลาร์เซลล์ #ศัพท์โซลาร์ #ความรู้โซลาร์ #ติดโซลาร์เซลล์ #เจาะลึกโซลาร์ #TNSSolar",
