    "fb": "ทำไมช่างโซลาร์ต้องมี Clamp Meter? 🔧\n\n1️⃣ วัดกระแสได้โดยไม่ต้องตัดวงจร แค่คล้องสาย\n2️⃣ รุ่นที่รองรับ DC วัดกระแสสตริงแผงและสายแบตเตอรี่ได้\n3️⃣ ใช้ได้ทั้งฝั่ง DC และ AC ในเครื่องเดียว\n4️⃣ หาสตริงผิดปกติได้เร็ว เทียบกระแสแต่ละสตริงตอนแสงเท่ากัน เช่น 8.20 A · 8.10 A · 4.50 A ← สตริงที่ 3 ต้องตรวจ\n\nวัดให้แม่น: คล้องสายเส้นเดียว · กด REL ปรับศูนย์ก่อนวัด · เลือกเครื่องที่มีพิกัดความปลอดภัยและย่านวัดเหมาะกับระบบ\nส่วนการวัดฉนวน ความต้านทานดิน และกราฟ I-V ต้องใช้เครื่องมือเฉพาะ\n\nทักมาปรึกษาทีม TNS Solar ได้เลยครับ\n\nLINE: @tnssolar\nโทร (แยกตามพื้นที่ติดตั้ง)\n• 081 796 4999 — กรุงเทพฯ นนทบุรี สมุทรปราการ (กฟน.)\n• 065 295 5998 — ชลบุรี ภาคกลาง ภาคตะวันออกเฉียงเหนือ (กฟภ.)\n• 087 304 3724 — เชียงใหม่ ภาคเหนือ (กฟภ.)\nเว็บไซต์: tnsnetwork\nสาขา: เชียงใหม่ | ชลบุรี | กรุงเทพมหานคร\n\n#ช่างโซลาร์ #ClampMeter #โซลาร์เซลล์ #เครื่องมือช่าง #เจาะลึกโซลาร์ #TNSSolar",
