    "fb": "เครื่องมือวัดของช่างโซลาร์ 6 อย่าง 🧰\n\n1️⃣ Digital Multimeter — วัดแรงดัน Voc ความต่อเนื่อง ขั้วบวก–ลบ\n2️⃣ Clamp Meter — วัดกระแส DC/AC ไม่ต้องตัดสาย\n3️⃣ Insulation Tester — ตรวจความเป็นฉนวนของสาย PV\n4️⃣ I-V Curve Tracer — ประเมินสมรรถนะแผงทั้งสตริง\n5️⃣ Irradiance Meter — วัดความเข้มแสง (W/m²) ใช้คู่กับอุณหภูมิแผง\n6️⃣ Earth Tester — วัดความต้านทานระบบสายดิน\n\nเลือกเครื่องมือ: รองรับแรงดัน DC สูงกว่าระบบ · พิกัดความปลอดภัย CAT III/IV · True RMS · สอบเทียบสม่ำเสมอ\n\nทักมาปรึกษาทีม TNS Solar ได้เลยครับ\n\nLINE: @tnssolar\nโทร (แยกตามพื้นที่ติดตั้ง)\n• 081 796 4999 — กรุงเทพฯ นนทบุรี สมุทรปราการ (กฟน.)\n• 065 295 5998 — ชลบุรี ภาคกลาง ภาคตะวันออกเฉียงเหนือ (กฟภ.)\n• 087 304 3724 — เชียงใหม่ ภาคเหนือ (กฟภ.)\nเว็บไซต์: tnsnetwork\nสาขา: เชียงใหม่ | ชลบุรี | กรุงเทพมหานคร\n\n#ช่างโซลาร์ #เครื่องมือช่าง #โซลาร์เซลล์ #ตรวจรับระบบ #เจาะลึกโซลาร์ #TNSSolar",
