    "file": "TNS-Deep_EP08_VO.mp4",
    "fileImg": "TNS-Post_เจาะลึกโซลาร์_08_Voc_4x5_v1.jpg",
    "fb": "Voc (Open-Circuit Voltage) คืออะไร? ⚡\n\nVoc คือแรงดันที่ขั้วแผงตอนไม่ต่อโหลด (กระแส = 0 A) เป็นแรงดันสูงสุดของแผง ณ แสงและอุณหภูมิขณะนั้น\n\n📈 บนกราฟ I-V: Voc อยู่ปลายสุด ส่วนจุดทำงานจริงคือ Vmp ซึ่งต่ำกว่าเสมอ\n❄️ อากาศเย็น Voc สูงขึ้น: Voc(T) = Voc × [1 + β × (T − 25)]\nตัวอย่างแผง 720 W Voc 49.4 V (β −0.24%/°C) ที่ 0°C ≈ 52.4 V\n\nนำไปใช้: ออกแบบจำนวนแผงต่อสตริง และเช็กว่า Voc รวมตอนเย็นสุดไม่เกินพิกัดแรงดัน DC ของอินเวอร์เตอร์\nVoc ไม่ได้ใช้คำนวณกำลังไฟ\n\nทักมาปรึกษาทีม TNS Solar ได้เลยครับ\n\nLINE: @tnssolar\nโทร (แยกตามพื้นที่ติดตั้ง)\n• 081 796 4999 — กรุงเทพฯ นนทบุรี สมุทรปราการ (กฟน.)\n• 065 295 5998 — ชลบุรี ภาคกลาง ภาคตะวันออกเฉียงเหนือ (กฟภ.)\n• 087 304 3724 — เชียงใหม่ ภาคเหนือ (กฟภ.)\nเว็บไซต์: tnsnetwork\nสาขา: เชียงใหม่ | ชลบุรี | กรุงเทพมหานคร\n\n#โซลาร์เซลล์ #Voc #ช่างโซลาร์ #ความรู้โซลาร์ #เจาะลึกโซลาร์ #TNSSolar",
    "tt": "Voc คือแรงดันวงจรเปิดของแผง อากาศเย็นยิ่งสูง ต้องใช้ออกแบบสตริงไม่ให้เกินพิกัดอินเวอร์เตอร์ ทักไลน์ @tnssolar\n#โซลาร์เซลล์ #Voc #ช่างโซลาร์ #ความรู้โซลาร์ #TNSSolar"
