    "fb": "MPPT คืออะไร? 🎯 (Maximum Power Point Tracking)\n\nแผงโซลาร์ไม่ใช่แหล่งจ่ายแรงดันคงที่ กระแสและแรงดันเปลี่ยนตามแสงและอุณหภูมิ และมีจุดที่ให้กำลังสูงสุดเพียงจุดเดียว (MPP: Pmax = Vmp × Imp)\n\nMPPT ในอินเวอร์เตอร์จะปรับแรงดันและกระแส เพื่อให้แผงทำงานที่จุดนี้ตลอดเวลา\n☀️ แสงมาก กำลังสูงขึ้น\n🌡 ร้อนขึ้น Vmp ลดลง จุด MPP เลื่อน\n❌ ถ้าไม่มี MPPT แผงจะทำงานผิดจุด ได้ไฟน้อยกว่าที่ควร\n\nอินเวอร์เตอร์หลาย MPPT: แยกแผงต่างทิศ ต่างมุม หรือที่มีเงาบัง ให้แต่ละชุดทำงานที่จุดสูงสุดของตัวเอง\n\nทักมาปรึกษาทีม TNS Solar ได้เลยครับ\n\nLINE: @tnssolar\nโทร (แยกตามพื้นที่ติดตั้ง)\n• 081 796 4999 — กรุงเทพฯ นนทบุรี สมุทรปราการ (กฟน.)\n• 065 295 5998 — ชลบุรี ภาคกลาง ภาคตะวันออกเฉียงเหนือ (กฟภ.)\n• 087 304 3724 — เชียงใหม่ ภาคเหนือ (กฟภ.)\nเว็บไซต์: tnsnetwork\nสาขา: เชียงใหม่ | ชลบุรี | กรุงเทพมหานคร\n\n#โซลาร์เซลล์ #MPPT #อินเวอร์เตอร์ #ความรู้โซลาร์ #เจาะลึกโซลาร์ #TNSSolar",
    "tt": "MPPT คือระบบในอินเวอร์เตอร์ที่หาจุดกำลังสูงสุดของแผงตลอดเวลา หลาย MPPT ยิ่งเหมาะกับหลังคาหลายทิศ ทักไลน์ @tnssolar\n#โซลาร์เซลล์ #MPPT #อินเวอร์เตอร์ #ความรู้โซลาร์ #TNSSolar"
