    "fb": "อ่านสเปกแผงโซลาร์จาก Datasheet เป็นไหม? 📄\nตัวอย่าง: Trina Solar Vertex N 720 W (TSM-NEG21C.20) แผง N-type i-TOPCon กระจก 2 ด้าน\n\n1️⃣ กำลังสูงสุด 720 W · ประสิทธิภาพ 23.2% → เลือกรุ่นให้เหมาะกับขนาดระบบ\n2️⃣ ขนาด 2384 × 1303 × 33 มม. · 38.3 กก. → เช็กพื้นที่และโครงสร้างหลังคา\n3️⃣ Vmp 41.3 V · Imp 17.44 A → ใช้ออกแบบสตริง\n4️⃣ Voc 49.4 V · Isc 18.49 A → ใช้เลือกสายไฟและอุปกรณ์ป้องกัน\n5️⃣ สัมประสิทธิ์อุณหภูมิ Pmax −0.29%/°C → ยิ่งติดลบน้อย ยิ่งทนร้อน\n6️⃣ รับประกันสินค้า 12 ปี · กำลังผลิต 30 ปี เหลือ 87.4%\n\nค่าทางไฟฟ้าวัดที่ STC (1,000 W/m², 25°C, AM 1.5)\n\nทักมาปรึกษาทีม TNS Solar ได้เลยครับ\n\nLINE: @tnssolar\nโทร (แยกตามพื้นที่ติดตั้ง)\n• 081 796 4999 — กรุงเทพฯ นนทบุรี สมุทรปราการ (กฟน.)\n• 065 295 5998 — ชลบุรี ภาคกลาง ภาคตะวันออกเฉียงเหนือ (กฟภ.)\n• 087 304 3724 — เชียงใหม่ ภาคเหนือ (กฟภ.)\nเว็บไซต์: tnsnetwork\nสาขา: เชียงใหม่ | ชลบุรี | กรุงเทพมหานคร\n\n#โซลาร์เซลล์ #แผงโซลาร์ #Datasheet #ความรู้โซลาร์ #เจาะลึกโซลาร์ #TNSSolar",
