    "fb": "Hot Spot (จุดร้อน) บนแผงโซลาร์ เกิดขึ้นได้อย่างไร? 🔥\n\n1️⃣ มีสิ่งบังแสงบางส่วน เช่น เงากิ่งไม้ เสาไฟ ฝุ่น หรือมูลนก\n2️⃣ เซลล์ในแผงต่ออนุกรม กระแสทั้งวงจรจึงลดลงเท่ากับเซลล์ที่ผลิตได้ต่ำสุด\n3️⃣ เซลล์ที่ถูกบังเปลี่ยนจาก \"ตัวผลิตไฟ\" กลายเป็น \"ภาระไฟฟ้า\" รับไฟจากเซลล์ข้างเคียง\n4️⃣ พลังงานกลายเป็นความร้อนสะสม จนแผงเสียหาย และเสี่ยงอัคคีภัยในระยะยาว\n\nป้องกันได้ ✅\n• Bypass Diode ในแผง ช่วยให้กระแสไหลข้ามกลุ่มเซลล์ที่โดนบัง\n• หมั่นล้างทำความสะอาดแผง กำจัดฝุ่นและมูลนก\n• ตัดแต่งกิ่งไม้รอบอาคาร\n• ตรวจด้วยกล้องถ่ายภาพความร้อนเป็นระยะ\n\nทักมาปรึกษาทีม TNS Solar ได้เลยครับ\n\nLINE: @tnssolar\nโทร (แยกตามพื้นที่ติดตั้ง)\n• 081 796 4999 — กรุงเทพฯ นนทบุรี สมุทรปราการ (กฟน.)\n• 065 295 5998 — ชลบุรี ภาคกลาง ภาคตะวันออกเฉียงเหนือ (กฟภ.)\n• 087 304 3724 — เชียงใหม่ ภาคเหนือ (กฟภ.)\nเว็บไซต์: tnsnetwork\nสาขา: เชียงใหม่ | ชลบุรี | กรุงเทพมหานคร\n\n#โซลาร์เซลล์ #HotSpot #ล้างแผงโซลาร์ #ความรู้โซลาร์ #เจาะลึกโซลาร์ #TNSSolar",
    "tt": "Hot Spot จุดร้อนบนแผง เกิดจากเงาบัง ฝุ่น มูลนก ป้องกันได้ด้วยการล้างแผงและตรวจระบบ ทักไลน์ @tnssolar\n#โซลาร์เซลล์ #HotSpot #ล้างแผงโซลาร์ #ความรู้โซลาร์ #TNSSolar"
