    "fb": "ทำไมแผงโซลาร์ผลิตไฟได้น้อยกว่าพิกัด Watt Peak บนป้าย? 🤔\n\n1️⃣ ตัวเลขบนป้ายวัดที่ STC: แสง 1,000 W/m² เซลล์ 25°C ในห้องแล็บ\n2️⃣ ความร้อน: เซลล์บนหลังคาร้อนถึง 60°C+ กำลังลดราว 0.3–0.4% ทุก 1°C ที่เกิน 25°C → หายไปราว 10%\n3️⃣ เงาบังและแผงไม่เท่ากัน: กระแสทั้งสตริงลดลงเท่าแผงที่ผลิตได้ต่ำสุด\n4️⃣ ฝุ่น คราบ และมูลนก: บังแสง ปล่อยไว้นานเสี่ยงจุดร้อน\n5️⃣ ทิศและมุมเอียง: หลังคาอาจไม่ได้หันรับแดดดีที่สุด\n6️⃣ การสูญเสียในระบบ: แรงดันตกในสาย DC ประสิทธิภาพอินเวอร์เตอร์ และการเสื่อมสภาพ\n\nออกแบบดี ติดตั้งถูกต้อง และดูแลสม่ำเสมอ ช่วยให้ได้ไฟใกล้ศักยภาพสูงสุด\n\nทักมาปรึกษาทีม TNS Solar ได้เลยครับ\n\nLINE: @tnssolar\nโทร (แยกตามพื้นที่ติดตั้ง)\n• 081 796 4999 — กรุงเทพฯ นนทบุรี สมุทรปราการ (กฟน.)\n• 065 295 5998 — ชลบุรี ภาคกลาง ภาคตะวันออกเฉียงเหนือ (กฟภ.)\n• 087 304 3724 — เชียงใหม่ ภาคเหนือ (กฟภ.)\nเว็บไซต์: tnsnetwork\nสาขา: เชียงใหม่ | ชลบุรี | กรุงเทพมหานคร\n\n#โซลาร์เซลล์ #WattPeak #ความรู้โซลาร์ #ลดค่าไฟ #เจาะลึกโซลาร์ #TNSSolar",
