    "title": "DC Arc Fault อาร์กไฟฟ้ากระแสตรง",
    "video": "v/ep13.mp4",
    "poster": "p/ep13.jpg",
    "img": "img/ep13.jpg",
    "thumb": "img/ep13.jpg",
    "ratio": "9/16",
    "imgRatio": "1080/1350",
    "file": "TNS-Deep_EP13_VO.mp4",
    "fileImg": "TNS-Post_เจาะลึกโซลาร์_13_DCArcFault_4x5_v1.jpg",
    "fb": "DC Arc Fault อาร์กไฟฟ้ากระแสตรง จุดเสี่ยงไฟไหม้ในระบบโซลาร์ ⚠️\n\n3 จุดเสี่ยงหลัก\n1️⃣ ขั้วต่อ DC (MC4) — พบปัญหาบ่อยที่สุด: ใช้ต่างยี่ห้อ/ต่างรุ่น ย้ำหัวไม่ถูกต้อง ขนาดไม่ตรงกับสาย\n2️⃣ สายไฟ DC — ใช้สาย AC แทนสาย PV ฉนวนแตกจากแดดและ UV ถูกสัตว์กัดแทะ\n3️⃣ กล่องต่อสายหลังแผง (Junction Box) — จุดเชื่อมต่อไม่สมบูรณ์ ซีลเสื่อมจนความชื้นเข้า\n\nกลไก: จุดต่อหลวม → ความต้านทานสูง ความร้อนสะสม → เกิดอาร์กที่ร้อนหลายพันองศา\n\nแนวทางป้องกัน ✅ ขั้วต่อยี่ห้อและรุ่นเดียวกัน · ย้ำหัวสายด้วยเครื่องมือเฉพาะ · ใช้สาย PV ที่ได้มาตรฐาน · ตัดไฟก่อนถอดขั้วต่อ · ตรวจเช็กเป็นระยะ\n\nข้อมูลอ้างอิง: การศึกษาของ TÜV Rheinland/Fraunhofer ISE และ BRE National Solar Centre พบว่าการติดตั้งผิดพลาดเป็นสาเหตุหลักของความเสียหายจากความร้อน และขั้วต่อ DC ต่างยี่ห้อเป็นต้นเหตุสำคัญของอาร์ก\n\nทักมาปรึกษาทีม TNS Solar ได้เลยครับ\n\nLINE: @tnssolar\nโทร (แยกตามพื้นที่ติดตั้ง)\n• 081 796 4999 — กรุงเทพฯ นนทบุรี สมุทรปราการ (กฟน.)\n• 065 295 5998 — ชลบุรี ภาคกลาง ภาคตะวันออกเฉียงเหนือ (กฟภ.)\n• 087 304 3724 — เชียงใหม่ ภาคเหนือ (กฟภ.)\nเว็บไซต์: tnsnetwork\nสาขา: เชียงใหม่ | ชลบุรี | กรุงเทพมหานคร\n\n#โซลาร์เซลล์ #ArcFault #ความปลอดภัย #ช่างโซลาร์ #เจาะลึกโซลาร์ #TNSSolar",
    "tt": "DC Arc Fault ต้นเหตุไฟไหม้โซลาร์ เกิดที่ขั้วต่อ MC4 บ่อยสุด ป้องกันได้ด้วยการติดตั้งที่ถูกต้อง ทักไลน์ @tnssolar\n#โซลาร์เซลล์ #ArcFault #ความปลอดภัย #ช่างโซลาร์ #TNSSolar"
