    "fb": "Rapid Shutdown ระบบหยุดทำงานฉุกเฉินในระบบโซลาร์ 🚒\n\nทำไมต้องมี? ตราบใดที่มีแสงแดด แผงโซลาร์ยังผลิตไฟ DC ตลอดเวลา แม้ตัดไฟ AC แล้ว สาย DC บนหลังคาก็ยังมีแรงดันหลายร้อยโวลต์ เสี่ยงไฟดูดขณะฉีดน้ำดับเพลิงหรือขึ้นไปซ่อมบำรุง\n\nหลักการ: กดสวิตช์หยุดทำงานฉุกเฉิน → อุปกรณ์ใต้แผงลดแรงดันในขอบเขตแผงให้เหลือไม่เกิน 80 V ภายใน 30 วินาที (ตามมาตรฐาน วสท. ระบบผลิตไฟฟ้าเซลล์แสงอาทิตย์บนหลังคา)\n\nตำแหน่งสวิตช์: ติดในจุดที่เจ้าหน้าที่มองเห็นและเข้าถึงง่าย เช่น ผนังทางเข้าหลักของอาคาร ห้ามซ่อนไว้ในห้องอินเวอร์เตอร์ และติดป้ายเตือนให้ชัดเจน\n\nทักมาปรึกษาทีม TNS Solar ได้เลยครับ\n\nLINE: @tnssolar\nโทร (แยกตามพื้นที่ติดตั้ง)\n• 081 796 4999 — กรุงเทพฯ นนทบุรี สมุทรปราการ (กฟน.)\n• 065 295 5998 — ชลบุรี ภาคกลาง ภาคตะวันออกเฉียงเหนือ (กฟภ.)\n• 087 304 3724 — เชียงใหม่ ภาคเหนือ (กฟภ.)\nเว็บไซต์: tnsnetwork\nสาขา: เชียงใหม่ | ชลบุรี | กรุงเทพมหานคร\n\n#โซลาร์เซลล์ #RapidShutdown #ความปลอดภัย #มาตรฐานวสท #เจาะลึกโซลาร์ #TNSSolar",
    "tt": "Rapid Shutdown ลดแรงดัน DC ในขอบเขตแผงเหลือ ≤ 80 V ภายใน 30 วินาที ปลอดภัยต่อนักดับเพลิง ทักไลน์ @tnssolar\n#โซลาร์เซลล์ #RapidShutdown #ความปลอดภัย #มาตรฐานวสท #TNSSolar"
