    "fb": "ติดโซลาร์แล้วกี่ปีคืนทุน?\nสูตร: ราคาระบบ ÷ ค่าไฟที่ประหยัดได้ต่อปี\n\nตัวอย่างระบบ 5 kW*\n• ราคาระบบ 175,000 บาท\n• ประหยัดได้ราว 2,400 บาท/เดือน = 28,800 บาท/ปี\n• คืนทุนประมาณ 6 ปี\n\nหลังคืนทุน แผงยังผลิตไฟต่อได้อีกเกือบ 20 ปี และถ้าใช้สิทธิ์โครงการรัฐ 50,000 บาท จะคืนทุนเร็วขึ้นอีก\n\nทักมาปรึกษาทีม TNS Solar ได้เลยครับ\n\nLINE: @tnssolar\nโทร (แยกตามพื้นที่ติดตั้ง)\n• 081 796 4999 — กรุงเทพฯ นนทบุรี สมุทรปราการ (กฟน.)\n• 065 295 5998 — ชลบุรี ภาคกลาง ภาคตะวันออกเฉียงเหนือ (กฟภ.)\n• 087 304 3724 — เชียงใหม่ ภาคเหนือ (กฟภ.)\nเว็บไซต์: tnsnetwork\nสาขา: เชียงใหม่ | ชลบุรี | กรุงเทพมหานคร\n\n*ตัวอย่าง Huawei 5 kW 1 เฟส ราคาเต็ม ณ พ.ย. 2569 · ผลจริงขึ้นกับการใช้ไฟและสภาพหลังคา\n\n#คืนทุนโซลาร์ #ติดโซลาร์เซลล์ #ลดค่าไฟ #ความรู้โซลาร์ #TNSSolar",
    "tt": "ระบบ 5 kW ราคา 175,000 บาท ประหยัดราว 28,800 บาท/ปี = คืนทุนประมาณ 6 ปี* แล้วใช้ต่ออีกเกือบ 20 ปี ทักไลน์ @tnssolar\n*ตัวอย่าง Huawei 5 kW 1 เฟส ราคาเต็ม ณ พ.ย. 2569 · ผลจริงขึ้นกับการใช้ไฟและสภาพหลังคา\n#คืนทุนโซลาร์ #ติดโซลาร์เซลล์ #ลดค่าไฟ #ความรู้โซลาร์ #TNSSolar"
