    "fb": "On-grid / Off-grid / Hybrid ต่างกันยังไง?\n🔌 On-grid — ต่อกับการไฟฟ้า ไม่มีแบต คุ้มค่าที่สุด นิยมที่สุด (ไฟดับระบบจะหยุดเพื่อความปลอดภัย)\n🔋 Hybrid — ต่อการไฟฟ้า + มีแบตเตอรี่ มีไฟสำรองตอนไฟดับ\n🌾 Off-grid — ไม่ต่อการไฟฟ้า ใช้แบตล้วน เหมาะพื้นที่ไม่มีไฟเข้า\n\nบ้านในเมืองทั่วไป เริ่มที่ On-grid คุ้มที่สุด และหลายรุ่นเพิ่มแบตเตอรี่ภายหลังได้*\n\nทักมาปรึกษาทีม TNS Solar ได้เลยครับ\n\nLINE: @tnssolar\nโทร (แยกตามพื้นที่ติดตั้ง)\n• 081 796 4999 — กรุงเทพฯ นนทบุรี สมุทรปราการ (กฟน.)\n• 065 295 5998 — ชลบุรี ภาคกลาง ภาคตะวันออกเฉียงเหนือ (กฟภ.)\n• 087 304 3724 — เชียงใหม่ ภาคเหนือ (กฟภ.)\nเว็บไซต์: tnsnetwork\nสาขา: เชียงใหม่ | ชลบุรี | กรุงเทพมหานคร\n\n*ขึ้นกับรุ่นอินเวอร์เตอร์\n\n#OnGrid #Hybrid #โซลาร์เซลล์ #ความรู้โซลาร์ #TNSSolar #ติดโซลาร์เซลล์",
    "tt": "On-grid คุ้มสุด · Hybrid มีไฟสำรอง · Off-grid สำหรับพื้นที่ไม่มีไฟเข้า บ้านคุณเหมาะกับแบบไหน? ทักมาปรึกษา TNS ได้เลย ทักไลน์ @tnssolar\n#OnGrid #Hybrid #โซลาร์เซลล์ #ความรู้โซลาร์ #TNSSolar"
