    "fb": "Micro Inverter หรือ String Inverter ดี?\n⚡ String — ต่อแผงเป็นสาย รวมเข้าเครื่องเดียว ราคาคุ้มค่า เหมาะกับหลังคาโล่ง หันทิศเดียว\n🔒 Micro — ติดใต้แผง ไฟ DC แรงดันต่ำ ปลอดภัยกว่า มีเงาบังกระทบเฉพาะแผงนั้น ดูข้อมูลรายแผง ขยายระบบง่าย\n\nTNS ติดตั้งได้ทั้ง 2 แบบ ส่งรูปหลังคามา เราช่วยแนะนำแบบที่เหมาะกับบ้านคุณ\n\nทักมาปรึกษาทีม TNS Solar ได้เลยครับ\n\nLINE: @tnssolar\nโทร (แยกตามพื้นที่ติดตั้ง)\n• 081 796 4999 — กรุงเทพฯ นนทบุรี สมุทรปราการ (กฟน.)\n• 065 295 5998 — ชลบุรี ภาคกลาง ภาคตะวันออกเฉียงเหนือ (กฟภ.)\n• 087 304 3724 — เชียงใหม่ ภาคเหนือ (กฟภ.)\nเว็บไซต์: tnsnetwork\nสาขา: เชียงใหม่ | ชลบุรี | กรุงเทพมหานคร\n\n#MicroInverter #StringInverter #โซลาร์เซลล์ #ความรู้โซลาร์ #TNSSolar #ติดโซลาร์เซลล์",
    "tt": "String คุ้มค่า เหมาะหลังคาโล่ง · Micro ปลอดภัยกว่า เหมาะหลังคาหลายทิศหรือมีเงา ส่งรูปหลังคามาให้ TNS ช่วยเลือก ทักไลน์ @tnssolar\n#MicroInverter #StringInverter #โซลาร์เซลล์ #ความรู้โซลาร์ #TNSSolar"
