    "tt": "หน่วยไฟกลางวัน ÷ 120 = ขนาดระบบที่ใช่ 5 kW ≈ 600 หน่วย/เดือน · 10 kW ≈ 1,200 หน่วย/เดือน* ส่งบิลค่าไฟมาให้ TNS ช่วยเลือก ทักไลน์ @tnssolar\n*1 kW ผลิตไฟประมาณ 120 หน่วย/เดือน ขึ้นกับทิศและสภาพหลังคา\n#ขนาดโซลาร์ #ติดโซลาร์เซลล์ #โซลาร์รูฟท็อป #ความรู้โซลาร์ #TNSSolar"
