    "tt": "หลังคาทิศใต้ผลิตไฟดีที่สุด ตะวันออก/ตะวันตกได้ราว 85–95%* มุมเอียงที่ดี ~15 องศา ระวังเงาบัง! ทักไลน์ @tnssolar\n*ค่าประมาณเทียบกับทิศใต้ ขึ้นกับความชันหลังคา\n#ทิศหลังคา #โซลาร์เซลล์ #โซลาร์รูฟท็อป #ความรู้โซลาร์ #TNSSolar"
